using System;using System.Data;using System.Drawing;using System.Windows.Forms;
namespace AshkanHotelManager{public partial class ReservationCalendarForm:Form{MonthCalendar cal;DataGridView grid;Label summary;public ReservationCalendarForm(){InitializeComponent();Text=App.T("calendar");BackColor=Ui.Bg;Build();ShowDay(DateTime.Today);App.ApplyDirection(this);}void Build(){var head=new Label{Text=App.T("calendar"),Dock=DockStyle.Top,Height=58,Font=Ui.Font(22,FontStyle.Bold),ForeColor=Ui.Text,Padding=new Padding(18)};Controls.Add(head);var left=Ui.SurfacePanel();left.Dock=App.Persian?DockStyle.Right:DockStyle.Left;left.Width=280;left.Padding=new Padding(18);cal=new MonthCalendar{MaxSelectionCount=1,Dock=DockStyle.Top};cal.DateSelected+=(s,e)=>ShowDay(e.Start);summary=new Label{Dock=DockStyle.Top,Height=80,Font=Ui.Font(10,FontStyle.Bold),ForeColor=Ui.Text,Padding=new Padding(5)};left.Controls.Add(summary);left.Controls.Add(cal);Controls.Add(left);grid=new DataGridView{Dock=DockStyle.Fill};Ui.Grid(grid);Controls.Add(grid);grid.BringToFront();head.BringToFront();}void ShowDay(DateTime d){var src=DataStore.Db.Tables["Reservations"];var t=src.Clone();int arrivals=0,departures=0;foreach(DataRow r in src.Rows){DateTime a,b;if(!DateTime.TryParse(Convert.ToString(r["CheckIn"]),out a)||!DateTime.TryParse(Convert.ToString(r["CheckOut"]),out b))continue;if(a.Date==d.Date){t.ImportRow(r);arrivals++;}else if(b.Date==d.Date){t.ImportRow(r);departures++;}else if(d.Date>a.Date&&d.Date<b.Date)t.ImportRow(r);}grid.DataSource=t;summary.Text=d.ToString("yyyy/MM/dd")+Environment.NewLine+App.T("arrivals")+": "+arrivals+"   •   "+App.T("departures")+": "+departures;}}}